const body = $json.body ?? $json;
const headers = $json.headers ?? {};
const jobId = body.job_id || $json.job_id || "";
const rawBody = JSON.stringify(body).replace(/'/g, "''");
const decision = body.decision || "approved";
const allowedDecision = ["approved", "rejected", "revision_requested"].includes(decision);
return [{
  json: {
    ...body,
    job_id: jobId,
    agent_secret: headers["x-agent-secret"] || headers["X-Agent-Secret"] || "",
    body_sql: rawBody,
    decision,
    allowed_decision: allowedDecision,
    reviewer_id: body.reviewer_id || "andy",
    reviewer_type: body.reviewer_type || ""
  }
}];
